macro_rules! Push {
    () => {
        # [doc = " Note that all sources can either be a ref-name, partial or full, or a rev-spec, unless specified otherwise, on the local side."] # [doc = " Destinations can only be a partial or full ref names on the remote side."] # [derive (PartialOrd , Ord , PartialEq , Eq , Copy , Clone , Hash , Debug)] pub enum Push < 'a > { # [doc = " Push all local branches to the matching destination on the remote, which has to exist to be updated."] AllMatchingBranches { # [doc = " If true, allow non-fast-forward updates of the matched destination branch."] allow_non_fast_forward : bool , } , # [doc = " Delete the destination ref or glob pattern, with only a single `*` allowed."] Delete { # [doc = " The reference or pattern to delete on the remote."] ref_or_pattern : & 'a BStr , } , # [doc = " Push a single ref or refspec to a known destination ref."] Matching { # [doc = " The source ref or refspec to push. If pattern, it contains a single `*`."] # [doc = " Examples are refnames like `HEAD` or `refs/heads/main`, or patterns like `refs/heads/*`."] src : & 'a BStr , # [doc = " The ref to update with the object from `src`. If `src`  is a pattern, this is a pattern too."] # [doc = " Examples are refnames like `HEAD` or `refs/heads/main`, or patterns like `refs/heads/*`."] dst : & 'a BStr , # [doc = " If true, allow non-fast-forward updates of `dest`."] allow_non_fast_forward : bool , } , # [doc = " Exclude a single ref."] Exclude { # [doc = " A full or partial ref name to exclude, or multiple if a single `*` is used."] src : & 'a BStr , } , }
    };
}

Push!();